"use client";

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Upload, FileText, ArrowLeft, Loader2, Info } from 'lucide-react';
import Link from 'next/link';
import toast from 'react-hot-toast';
import api from '@/services/api';
import { Stepper } from '@/components/Stepper';
import { useAuthStore } from '@/store/useAuthStore';
import SuratPermohonanTemplate from '@/components/SuratPermohonanTemplate';
import { useRef } from 'react';

export default function BuatPermohonanPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const { user } = useAuthStore();
  const templateRef = useRef<HTMLDivElement>(null);
  
  const [formData, setFormData] = useState({
    purpose: '',
    application_type: 'Sewa Hanggar',
  });

  const [officialLetter, setOfficialLetter] = useState<File | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleDownloadTemplate = async () => {
    if (!templateRef.current) return;
    try {
      setLoading(true);
      const html2pdf = (await import('html2pdf.js')).default;
      const element = templateRef.current;
      const opt = {
        margin: 0,
        filename: `Template_Permohonan_${formData.application_type.replace(/\s+/g, '_')}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      
      html2pdf().set(opt).from(element).save();
      toast.success('Template berhasil diunduh. Silakan lengkapi, tandatangani, dan unggah kembali.');
    } catch (error) {
      console.error(error);
      toast.error('Gagal mengunduh template surat.');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!officialLetter) {
      toast.error('Harap unggah Surat Permohonan Resmi!');
      return;
    }
    
    setLoading(true);
    
    try {
      const payload = new FormData();
      payload.append('purpose', formData.purpose);
      payload.append('application_type', formData.application_type);
      payload.append('official_letter', officialLetter);
      
      const response = await api.post('/rentals', payload, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      });
      
      toast.success('Surat permohonan berhasil diajukan! Menunggu verifikasi Kadis.');
      // After success, navigate to the detail page (or back to list)
      router.push(`/tenant/permohonan/${response.data.data.id}`);
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Terjadi kesalahan saat mengajukan permohonan');
      setLoading(false);
    }
  };

  return (
    <div className="p-4 md:p-8 bg-slate-50 min-h-screen">
      <div className="max-w-5xl mx-auto">
        <div className="mb-6">
          <Link href="/tenant/permohonan" className="inline-flex items-center text-sm text-slate-500 hover:text-blue-600 transition-colors mb-4">
            <ArrowLeft className="w-4 h-4 mr-1" /> Kembali ke Daftar Permohonan
          </Link>
          <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Buat Permohonan Baru</h1>
          <p className="text-slate-500 mt-1">Langkah 1: Unggah Surat Permohonan Resmi</p>
        </div>

        {/* Stepper Component */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mb-8">
          <Stepper currentStep={1} />
        </div>

        <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-slate-800 px-6 py-4 flex items-center gap-3">
            <FileText className="w-5 h-5 text-amber-400" />
            <h2 className="text-white font-semibold tracking-wide">Surat Permohonan Resmi</h2>
          </div>
          
          <div className="p-6 md:p-8 space-y-8">
            <div className="bg-blue-50 border border-blue-100 rounded-lg p-5 flex gap-4 text-blue-800">
              <Info className="w-6 h-6 flex-shrink-0 text-blue-500 mt-0.5" />
              <div>
                <h4 className="font-bold mb-1">Alur Permohonan Baru</h4>
                <p className="text-sm leading-relaxed">
                  Pada tahap ini Anda hanya perlu mengunggah <strong>Surat Permohonan Resmi</strong> (ber-Kop Surat, ditandatangani, dan distempel). Setelah Kepala Dinas (Kadis) menyetujui surat tersebut, Anda akan dapat memilih detail layanan sewa (aset, durasi, armada) pada langkah selanjutnya.
                </p>
              </div>
            </div>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-slate-800 mb-2">Tujuan / Perihal Permohonan <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  name="purpose" 
                  value={formData.purpose} 
                  onChange={handleChange} 
                  required
                  placeholder="Contoh: Permohonan Sewa Hanggar untuk Perawatan Pesawat"
                  className="w-full border-2 border-slate-200 px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-50 transition-all font-medium"
                />
              </div>

              <div>
                <label className="block text-sm font-bold text-slate-800 mb-2">Unggah File Surat <span className="text-red-500">*</span></label>
                <div className="mt-1 flex justify-center px-6 pt-8 pb-8 border-2 border-slate-300 border-dashed rounded-xl hover:bg-slate-50 transition-colors">
                  <div className="space-y-2 text-center">
                    <Upload className="mx-auto h-10 w-10 text-slate-400" />
                    <div className="flex text-sm text-slate-600 justify-center">
                      <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-bold text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500 px-2 py-1">
                        <span>Pilih file PDF</span>
                        <input 
                          id="file-upload" 
                          name="file-upload" 
                          type="file" 
                          className="sr-only" 
                          accept=".pdf"
                          onChange={(e) => {
                            if (e.target.files && e.target.files[0]) {
                              setOfficialLetter(e.target.files[0]);
                            }
                          }}
                        />
                      </label>
                      <p className="pl-1 py-1">atau drag and drop</p>
                    </div>
                    <p className="text-xs text-slate-500">PDF maksimal 5MB</p>
                    
                    {officialLetter && (
                      <div className="mt-4 p-3 bg-emerald-50 text-emerald-700 rounded text-sm font-bold flex items-center justify-center border border-emerald-200">
                        <FileText className="w-4 h-4 mr-2" /> {officialLetter.name}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
            
            <div className="pt-6 border-t border-slate-100 flex justify-end">
              <button 
                type="submit" 
                disabled={loading}
                className="bg-blue-600 hover:bg-blue-700 text-white py-3 px-8 rounded-lg font-bold transition-all shadow-md hover:shadow-lg disabled:opacity-70 disabled:cursor-not-allowed flex items-center"
              >
                {loading && <Loader2 className="w-5 h-5 animate-spin mr-2" />}
                Kirim Surat Permohonan
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
