import React from 'react';
import { Upload, FileCheck, MapPin, CheckCircle, PenTool, CheckCircle2 } from 'lucide-react';

interface StepperProps {
  currentStep: number; // 1 to 6
}

export const Stepper: React.FC<StepperProps> = ({ currentStep }) => {
  const steps = [
    { id: 1, title: 'Upload Surat', description: 'Surat Permohonan', icon: <Upload size={24} />, color: 'bg-amber-400', borderColor: 'border-amber-400' },
    { id: 2, title: 'Verifikasi Kadis', description: 'Persetujuan Surat', icon: <FileCheck size={24} />, color: 'bg-lime-500', borderColor: 'border-lime-500' },
    { id: 3, title: 'Pilih Layanan', description: 'Detail Aset', icon: <MapPin size={24} />, color: 'bg-emerald-500', borderColor: 'border-emerald-500' },
    { id: 4, title: 'Validasi Admin', description: 'Cek Kapasitas', icon: <CheckCircle size={24} />, color: 'bg-cyan-500', borderColor: 'border-cyan-500' },
    { id: 5, title: 'Draft Kontrak', description: 'Pembuatan PKS', icon: <PenTool size={24} />, color: 'bg-blue-500', borderColor: 'border-blue-500' },
    { id: 6, title: 'Selesai', description: 'Kontrak Aktif', icon: <CheckCircle2 size={24} />, color: 'bg-purple-500', borderColor: 'border-purple-500' },
  ];

  return (
    <div className="w-full py-10 overflow-x-auto bg-slate-50 border-b border-slate-200">
      <div className="flex justify-between items-start min-w-[800px] max-w-5xl mx-auto px-4 relative">
        
        {steps.map((step, index) => {
          const isCompleted = currentStep > step.id;
          const isCurrent = currentStep === step.id;

          return (
            <div key={step.id} className="flex flex-col items-center relative w-1/6">
              
              {/* Connector Arrow Style */}
              {index < steps.length - 1 && (
                <div className={`absolute top-[40px] left-[55%] w-[90%] h-[12px] z-0 flex items-center`}>
                  <div className={`w-full h-[4px] ${isCompleted ? step.color : 'bg-slate-200'} transition-all duration-500`}></div>
                  {/* CSS Arrow head pointing right */}
                  <div className={`w-0 h-0 border-t-[8px] border-t-transparent border-b-[8px] border-b-transparent border-l-[12px] 
                    ${isCompleted ? step.color.replace('bg-', 'border-l-') : 'border-l-slate-200'} transition-all duration-500 -ml-1`}>
                  </div>
                </div>
              )}

              {/* Circle Icon Container */}
              <div className="relative z-10 mb-2 group cursor-default">
                <div className={`w-[80px] h-[80px] rounded-full flex items-center justify-center transition-all duration-500 relative
                  ${isCompleted ? step.color + ' text-white shadow-md' : isCurrent ? 'bg-white border-[6px] ' + step.borderColor + ' ' + step.color.replace('bg-', 'text-') : 'bg-white border-[6px] border-slate-100 text-slate-300'}
                  ${isCurrent ? 'shadow-xl scale-110 z-20' : 'shadow-sm z-10'}
                `}>
                  {/* Outer glow for current step */}
                  {isCurrent && (
                    <div className={`absolute -inset-2 rounded-full ${step.color} opacity-20 animate-pulse`}></div>
                  )}
                  {step.icon}
                </div>
                
                {/* Arrow Pointer (like in the image pointing to STEP 01 banner) */}
                <div className={`w-0 h-0 border-l-[12px] border-l-transparent border-r-[12px] border-r-transparent border-t-[12px] mx-auto -mb-2 mt-[4px]
                  ${isCompleted || isCurrent ? step.color.replace('bg-', 'border-t-') : 'border-t-transparent'} transition-all duration-500
                `}></div>
              </div>

              {/* Text / Step Ribbon */}
              <div className="text-center px-1 mt-2 z-10 relative">
                <div className={`relative px-4 py-1.5 rounded-sm overflow-hidden group shadow-sm flex items-center justify-center
                  ${isCompleted || isCurrent ? step.color : 'bg-slate-200'} transition-all duration-500`}>
                  
                  {/* Ribbon arrow effect */}
                  <div className={`absolute top-0 right-0 w-4 h-full bg-white opacity-20 transform translate-x-2 skew-x-[-20deg]`}></div>
                  
                  <span className={`text-[11px] font-black uppercase tracking-wider relative z-10 ${isCompleted || isCurrent ? 'text-white' : 'text-slate-400'}`}>
                    STEP {step.id < 10 ? `0${step.id}` : step.id}
                  </span>
                </div>
                
                <h4 className={`font-bold mt-3 text-[14px] ${isCurrent ? 'text-slate-900 scale-105' : isCompleted ? 'text-slate-700' : 'text-slate-400'} transition-all duration-300`}>
                  {step.title}
                </h4>
                <p className={`text-[11px] mt-1 leading-tight ${isCurrent ? 'text-slate-600 font-medium' : 'text-slate-400'}`}>
                  {step.description}
                </p>
              </div>

            </div>
          );
        })}

      </div>
    </div>
  );
};
